def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        row_coords = []
        for j, val in enumerate(row):
            if val == x:
                row_coords.append((i, j))
        # Sort coordinates in this row by column in descending order
        row_coords.sort(key=lambda coord: coord[1], reverse=True)
        result.extend(row_coords)
    # The outer list is already in ascending row order due to enumeration
    return result

def get_row(lst, x):
    result = []
    for row_idx, row in enumerate(lst):
        # Find all column indices where value equals x
        col_indices = [col_idx for col_idx, val in enumerate(row) if val == x]
        # Sort column indices in descending order
        col_indices.sort(reverse=True)
        for col_idx in col_indices:
            result.append((row_idx, col_idx))
    return result

