    for i, row in enumerate(lst):
        # Find all column indices where value equals x in this row
        cols = [j for j, val in enumerate(row) if val == x]
        # Sort columns in descending order
        cols.sort(reverse=True)
        for col in cols:
            result.append((i, col))
    return result

def sort_array(array):
    if not array:
        return []

    first = array[0]
    last = array[-1]
    total = first + last

    if total % 2 == 1:
        return sorted(array)
    else:
        return sorted(array, reverse=True)

