def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            # Determine the base ASCII value depending on case
            base = ord('a') if char.islower() else ord('A')
            # Shift down by 2 * 2 = 4 places
            shifted = (ord(char) - base + 4) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)

def encode(message):
    vowels = 'aeiouAEIOU'
    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }
    result = []
    for char in message:
        if char in vowels:
            result.append(vowel_map[char])
